template <class T>
class CowPtr {
    std::shared_ptr<T> p_;
    void detach() { if (p_.use_count() != 1) p_ = std::make_shared<T>(*p_); }
public:
    const T& operator*() const { return *p_; }   // readers share, no lock
    T& operator*() { detach(); return *p_; }     // writer clones once, then mutates
};

