std::atomic<std::shared_ptr<const Config>> current;

std::shared_ptr<const Config> read() { return current.load(); }   /* lock-free-ish */

void update(std::function<void(Config&)> edit) {
    static std::mutex write;
    std::lock_guard lock(write);                       /* writers serialise */
    auto next = std::make_shared<Config>(*current.load());  /* copy-on-write */
    edit(*next);
    current.store(next);                               /* publish the snapshot */
}
